const fs=require('fs'),assert=require('node:assert/strict'),{DatabaseSync}=require('node:sqlite');const root='C:/ProgramData/Seerr/data',entry='https://letterboxd.com/prplmg/film/iboy/',eventId='tautulli:99c72463778de0c815b5bc16d0ca9b45da15bcaab95e2f48499a5995d8824b4a';
const event=JSON.parse(fs.readFileSync(root+'/letterboxd-playback-events.json')).events.find(e=>e.id===eventId);assert.equal(event.userId,1);assert.equal(event.tmdbId,414190);assert.equal(event.watchedDate,'2026-10-28');
const receipts=JSON.parse(fs.readFileSync(root+'/letterboxd-sync-receipts.json')).entries;const party=receipts.filter(r=>r.userId===1&&r.entryId===entry&&r.originId.startsWith('party:'));assert.equal(party.length,1);assert.equal(party[0].diaryBaseline.watchedDate,event.watchedDate);
const db=new DatabaseSync(root+'/db/db.sqlite3');db.exec('PRAGMA busy_timeout=5000; BEGIN IMMEDIATE');try{const row=db.prepare("SELECT * FROM movie_review WHERE id=? AND userId=1").get('local:1:414190:6d0d9087-4c13-4f0b-ade6-e2be1f5b32e7');assert.equal(row.externalEntryId,entry);assert.equal(row.watchedDate,event.watchedDate);assert.equal(row.syncToLetterboxd,1);assert(row.viewingEventId===null||row.viewingEventId===eventId);if(row.viewingEventId!==eventId){fs.writeFileSync(root+'/iboy-viewing-consolidation-20261030.json',JSON.stringify({reason:'User explicitly confirmed Plex and party are the same viewing',row,event,partyReceipt:party[0]}),{flag:'wx',mode:0o600});db.prepare('UPDATE movie_review SET viewingEventId=? WHERE id=?').run(eventId,row.id);}db.exec('COMMIT');console.log(JSON.stringify({consolidated:true,viewingEventId:eventId,entry,remoteWrites:0,deletedRows:0}));}catch(e){db.exec('ROLLBACK');throw e}finally{db.close()}
